import os from 'node:os';const HOME=os.homedir().split(String.fromCharCode(92)).join('/');
import fs from 'node:fs';import zlib from 'node:zlib';
const source=fs.readFileSync('runtime/resources/app/server.mjs','utf8');const start=source.indexOf('function zstdFrames(');const stop=source.indexOf('function dshSessionLines(',start);const frames=new Function('zlib',source.slice(start,stop)+';return zstdFrames;')(zlib);
const base=HOME+'/.dsh/sessions/--D-dsh--';const files=fs.readdirSync(base).map(sid=>({sid,file:base+'/'+sid+'/session.v4.jsonl.zstd'})).filter(r=>fs.existsSync(r.file)).sort((a,b)=>fs.statSync(b.file).mtimeMs-fs.statSync(a.file).mtimeMs).slice(0,2);
for(const r of files){const data=frames(fs.readFileSync(r.file),Infinity);const lines=Buffer.concat(data).toString().split('\n').filter(Boolean).map(l=>{try{return JSON.parse(l)}catch{return null}}).filter(Boolean);const counts={};for(const j of lines)counts[j.type]=(counts[j.type]||0)+1;console.log(JSON.stringify({sid:r.sid,frames:data.length,lines:lines.length,header:lines[0],types:counts,tail:lines.slice(-8).map(j=>({type:j.type,time:j.time,keys:Object.keys(j),dataKeys:Object.keys(j.data||{}),inserted:j.data?.inserted?.map(x=>({keys:Object.keys(x),source:x.source,content:x.content?.map(c=>({type:c.type,text:typeof c.text==='string'?c.text.slice(0,100):undefined}))})),message:j.data?.message?{keys:Object.keys(j.data.message),role:j.data.message.role,content:j.data.message.content?.map(c=>({type:c.type,text:c.text?.slice(0,100)}))}:undefined}))}));}
